import{_ as i,C as a,o as n,c as s,j as t,a as e,E as o,aj as c}from"./chunks/framework.m090XgxO.js";const y=JSON.parse('{"title":"KbdGroup","description":"","frontmatter":{},"headers":[],"relativePath":"components/kbd-group.md","filePath":"components/kbd-group.md","lastUpdated":1789206102000}'),h={name:"components/kbd-group.md"},b={id:"kbdgroup",tabindex:"-1"};function p(u,d,k,g,f,m){const l=a("Badge"),r=a("XhDemo");return n(),s("div",null,[t("h1",b,[d[0]||(d[0]=e("KbdGroup ",-1)),o(l,{type:"info",text:"键帽组"}),d[1]||(d[1]=e()),d[2]||(d[2]=t("a",{class:"header-anchor",href:"#kbdgroup","aria-label":'Permalink to "KbdGroup <Badge type="info" text="键帽组" />"'},"​",-1))]),d[3]||(d[3]=c('<p>把一组按键按当前平台格式化成完整快捷键提示，不注册任何监听。行为由<a href="./hotkeys">快捷键</a>负责，单枚说明用<a href="./kbd">键帽</a>。</p><div class="xh-resource-links"><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/engine/headless/src/kbd-group" target="_blank" rel="noreferrer">Headless</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/design/styles/css/kbd-group.css" target="_blank" rel="noreferrer">Styles</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/vue/src/components/kbd-group" target="_blank" rel="noreferrer">Vue</a><a href="https://github.com/XiHanFun/XiHan.UI/tree/dev/ui/packages/adapters/react/src/components/kbd-group" target="_blank" rel="noreferrer">React</a><a href="https://github.com/XiHanFun/XiHan.UI/blob/dev/ui/packages/adapters/web-components/src/elements/kbd-group.ts" target="_blank" rel="noreferrer">Web Components</a></div><h2 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法&quot;">​</a></h2><p>同一份 keys 两套写法：Mac 出符号且键帽连排，其余平台出单词并用加号连接</p>',4)),o(r,{src:"kbd-group/01-platform"}),d[4]||(d[4]=t("h2",{id:"示例",tabindex:"-1"},[e("示例 "),t("a",{class:"header-anchor",href:"#示例","aria-label":'Permalink to "示例"'},"​")],-1)),d[5]||(d[5]=t("h3",{id:"尺寸",tabindex:"-1"},[e("尺寸 "),t("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),d[6]||(d[6]=t("p",null,"size 换的是字号与键帽的内边距，三档与其余控件同源",-1)),o(r,{src:"kbd-group/02-size"}),d[7]||(d[7]=t("h3",{id:"禁用",tabindex:"-1"},[e("禁用 "),t("a",{class:"header-anchor",href:"#禁用","aria-label":'Permalink to "禁用"'},"​")],-1)),d[8]||(d[8]=t("p",null,"展示状态由作者显式给出，不从 Hotkeys enabled 暗中推导",-1)),o(r,{src:"kbd-group/03-disabled"}),d[9]||(d[9]=t("h3",{id:"多组合换行",tabindex:"-1"},[e("多组合换行 "),t("a",{class:"header-anchor",href:"#多组合换行","aria-label":'Permalink to "多组合换行"'},"​")],-1)),d[10]||(d[10]=t("p",null,"每组内部不拆行，容器只在完整组合之间换行",-1)),o(r,{src:"kbd-group/04-wrap"}),d[11]||(d[11]=c('<h2 id="设计指引" tabindex="-1">设计指引 <a class="header-anchor" href="#设计指引" aria-label="Permalink to &quot;设计指引&quot;">​</a></h2><h3 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h3><ul><li>在菜单、命令面板、按钮提示或快捷键速查表中展示完整组合。</li><li>同一份 <code>keys</code> 需要在 Mac 与 Windows/Linux 上使用各自熟悉的写法。</li></ul><h3 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h3><ul><li>注册键盘动作：用<a href="./hotkeys">快捷键</a>。</li><li>只显示一枚键：用<a href="./kbd">键帽</a>。</li></ul><h3 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h3><ul><li>Mac 使用符号并连排；其他平台使用文字和统一基线的 <code>+</code>。</li><li>整组不会为了展示安装全局监听；<code>disabled</code> 与 <code>pressed</code> 只是显式展示事实。</li><li>组合保持为不可拆分的行内单元，多个组合可以在外层自然换行。</li><li>M1 实体键帽使用等宽字、1px edge、顶部高光和底部 contact shadow。</li></ul><h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-kbd-group&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhKbdGroup</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/kbd-group.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;kbd-group&quot;</code>：<strong><code>root</code></strong> · <code>key</code> · <code>separator</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>组合所提示的动作是否不可用。</td></tr><tr><td><code>keys</code></td><td><code>string[]</code></td><td>是</td><td>组合里的各枚键，例如 [&#39;Mod&#39;, &#39;Shift&#39;, &#39;P&#39;]。</td></tr><tr><td><code>platform</code></td><td><code>HotkeysPlatform</code></td><td></td><td>平台写法；auto 在适配器测出平台前按 other。</td></tr><tr><td><code>pressed</code></td><td><code>boolean</code></td><td></td><td>整组是否正在被真实动作激活；纯展示默认静止。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;KbdGroupTranslations&gt;</code></td><td></td><td>读屏文案覆盖。</td></tr></tbody></table><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>connect</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>segments</code></td><td><code>readonly HotkeySegment[]</code></td><td>翻好的各枚键，顺序与 keys 一致。</td></tr><tr><td><code>platform</code></td><td><code>HotkeysResolvedPlatform</code></td><td>实际采用的平台写法。</td></tr><tr><td><code>separator</code></td><td><code>string</code></td><td>Mac 为空串，其余平台为 +。</td></tr><tr><td><code>segmentOf</code></td><td><code>(value: string) =&gt; HotkeySegment | null</code></td><td>按原始声明取回一枚键。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getKeyProps</code></td><td><code>(props: KbdGroupKeyProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getSeparatorProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/practices/names-and-descriptions/" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-label</code></td><td>props.translations?.hotkey?.(names)</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;img&#39;</td></tr><tr><td><code>key</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>separator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr></tbody></table><ul><li>root 以一个组级 <code>aria-label</code> 朗读完整组合，视觉键帽和连接符全部 <code>aria-hidden</code>，不会重复念。</li><li><code>keys</code> 必填且不能为空；无效组合直接报错，不产生无名称图像。</li></ul><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/kbd-group.css</code> 按部件选择：<code>[data-scope=&quot;kbd-group&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><p><code>forced-colors: active</code> 下另有一套规则：颜色交给系统，边框与状态标记改用系统色关键字。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-platform</code></td><td>resolveHotkeysPlatform(props.platform)</td></tr><tr><td><code>root</code></td><td><code>data-pressed</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>key</code></td><td><code>data-modifier</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件公开覆盖槽由独立皮肤的实际消费位生成；缺省来源、作用部件和状态均与 CSS 同源。</p><table tabindex="0"><thead><tr><th>变量</th><th>部件</th><th>CSS 属性</th><th>状态</th><th>缺省来源</th><th>说明</th></tr></thead><tbody><tr><td><code>--xh-kbd-group-fg</code></td><td><code>root</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-muted</code></td><td>kbd-group 的 root 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-kbd-group-font-size</code></td><td><code>root</code></td><td><code>font-size</code></td><td><code>default</code></td><td><code>--xh-_kbd-group-font-size</code></td><td>kbd-group 的 root 部件 font-size 覆盖槽。</td></tr><tr><td><code>--xh-kbd-group-gap</code></td><td><code>root</code></td><td><code>gap</code></td><td><code>default</code></td><td><code>--xh-space-0_5</code></td><td>kbd-group 的 root 部件 gap 覆盖槽。</td></tr><tr><td><code>--xh-kbd-group-key-bg</code></td><td><code>key</code></td><td><code>background</code></td><td><code>default</code></td><td><code>--xh-material-soft-bg</code></td><td>kbd-group 的 key 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-kbd-group-key-bg-disabled</code></td><td><code>key</code><br><code>root</code></td><td><code>background</code></td><td><code>disabled</code></td><td><code>--xh-bg-muted</code></td><td>kbd-group 的 key、root 部件 background 覆盖槽。</td></tr><tr><td><code>--xh-kbd-group-key-border</code></td><td><code>key</code></td><td><code>border</code></td><td><code>default</code></td><td><code>--xh-material-soft-border</code></td><td>kbd-group 的 key 部件 border 覆盖槽。</td></tr><tr><td><code>--xh-kbd-group-key-fg</code></td><td><code>key</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-default</code></td><td>kbd-group 的 key 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-kbd-group-key-fg-disabled</code></td><td><code>key</code><br><code>root</code></td><td><code>color</code></td><td><code>disabled</code></td><td><code>--xh-fg-subtle</code></td><td>kbd-group 的 key、root 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-kbd-group-key-fg-modifier</code></td><td><code>key</code></td><td><code>color</code></td><td><code>modifier</code></td><td><code>--xh-fg-muted</code></td><td>kbd-group 的 key 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-kbd-group-key-font</code></td><td><code>key</code></td><td><code>font-family</code></td><td><code>default</code></td><td><code>--xh-font-family-mono</code></td><td>kbd-group 的 key 部件 font-family 覆盖槽。</td></tr><tr><td><code>--xh-kbd-group-key-font-weight</code></td><td><code>key</code></td><td><code>font-weight</code></td><td><code>default</code></td><td><code>--xh-font-weight-medium</code></td><td>kbd-group 的 key 部件 font-weight 覆盖槽。</td></tr><tr><td><code>--xh-kbd-group-key-min-w</code></td><td><code>key</code></td><td><code>min-inline-size</code></td><td><code>default</code></td><td><code>--xh-control-indicator-size</code></td><td>kbd-group 的 key 部件 min-inline-size 覆盖槽。</td></tr><tr><td><code>--xh-kbd-group-key-px</code></td><td><code>key</code></td><td><code>padding-inline</code></td><td><code>default</code></td><td><code>--xh-_kbd-group-key-px</code></td><td>kbd-group 的 key 部件 padding-inline 覆盖槽。</td></tr><tr><td><code>--xh-kbd-group-key-py</code></td><td><code>key</code></td><td><code>padding-block</code></td><td><code>default</code></td><td><code>--xh-space-0_5</code></td><td>kbd-group 的 key 部件 padding-block 覆盖槽。</td></tr><tr><td><code>--xh-kbd-group-key-radius</code></td><td><code>key</code></td><td><code>border-radius</code></td><td><code>default</code></td><td><code>--xh-shape-inset</code></td><td>kbd-group 的 key 部件 border-radius 覆盖槽。</td></tr><tr><td><code>--xh-kbd-group-key-shadow</code></td><td><code>key</code></td><td><code>box-shadow</code></td><td><code>default</code></td><td><code>--xh-stroke-thin</code></td><td>kbd-group 的 key 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-kbd-group-key-shadow-pressed</code></td><td><code>key</code><br><code>root</code></td><td><code>box-shadow</code></td><td><code>active</code><br><code>disabled</code><br><code>is(button, a[href], [role=&#39;button&#39;], [role=&#39;menuitem&#39;], [role=&#39;option&#39;])</code><br><code>not([data-disabled])</code><br><code>not([disabled], [aria-disabled=&#39;true&#39;])</code><br><code>pressed</code></td><td><code>--xh-stroke-thin</code></td><td>kbd-group 的 key、root 部件 box-shadow 覆盖槽。</td></tr><tr><td><code>--xh-kbd-group-separator-fg</code></td><td><code>separator</code></td><td><code>color</code></td><td><code>default</code></td><td><code>--xh-fg-subtle</code></td><td>kbd-group 的 separator 部件 color 覆盖槽。</td></tr><tr><td><code>--xh-kbd-group-separator-fg-disabled</code></td><td><code>root</code><br><code>separator</code></td><td><code>color</code></td><td><code>disabled</code></td><td><code>--xh-fg-subtle</code></td><td>kbd-group 的 root、separator 部件 color 覆盖槽。</td></tr></tbody></table><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p><code>background-color</code> · <code>border-color</code> · <code>box-shadow</code> · <code>color</code> · <code>translate</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><p>键位顺序保持物理键盘的 LTR 顺序，并用 unicode bidi 隔离，不受周围文本方向重排。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>放在 Menu/ContextMenu/Command 条目末端时用 <code>margin-inline-start: auto</code> 对齐。</li><li>与 Hotkeys 使用同一份 <code>keys</code>，由业务显式组合展示和行为。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>一律写 <code>Mod</code> 作为跨平台主修饰键。</li><li>只有对应动作不可用时才设置 <code>disabled</code>，不要从行为组件暗中推导视觉状态。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>用 Hotkeys 组件代替 KbdGroup 只为了显示。</li><li>手写 <code>Ctrl+S</code> 文本，导致 Mac 显示与真实组合不一致。</li></ul>',45))])}const q=i(h,[["render",p]]);export{y as __pageData,q as default};
